// Whitelist explicita (regra permanente do projeto) -- reconstroi campo a
// campo mesmo sendo o retorno ja minimo da RPC.
const row = $input.first()?.json?.resultado || {};
return [{ json: {
  autorizado: !!row.autorizado,
  aguardando_confirmacao: !!row.aguardando_confirmacao,
  motivo: row.motivo || null,
  itens: (row.itens || []).map(i => ({
    produto_id: i.produto_id, nome: i.nome, quantidade: i.quantidade,
    preco_unitario: i.preco_unitario, subtotal: i.subtotal,
  })),
  subtotal: row.subtotal,
  frete_disponivel: row.frete_disponivel,
  valor_frete: row.valor_frete,
  prazo_estimado_min: row.prazo_estimado_min,
  total: row.total,
} }];

function tryGet(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const trigger = $('When Executed by Another Workflow').item.json;
const resultado = tryGet('Montar Resultado');
const blacklist = ['p_empresa_id','p_cliente_id','p_conversa_id','p_mensagem_id','p_atendimento_id'];
const input = {};
for (const k of Object.keys(trigger || {})) {
  if (!blacklist.includes(k)) input[k] = trigger[k];
}
return [{ json: {
  empresa_id: trigger.p_empresa_id,
  conversa_id: trigger.p_conversa_id || null,
  mensagem_id: trigger.p_mensagem_id || null,
  atendimento_id: trigger.p_atendimento_id || null,
  tool_nome: 'revisar_carrinho',
  detalhes: JSON.stringify({ input, output: resultado }),
  resultado_original: resultado,
} }];

